	MOV	AL,42
	DEC	CH
; *** WARNING: DJNZ does not affect flags - DEC does.
	JNZ	TARGET
	INB	2
	OUTB	3
	LAHF
	XCHG	AH,AL
	PUSH	AX
	XCHG	AH,AL
	POP	AX
	XCHG	AH,AL
	SAHF
	UP
	MOV	DI,BX
	REPNZ
	SCAB
	MOV	BX,DI
	DOWN
	MOV	SI,BX
	MOV	DI,DX
	REP
	MOVB
	MOV	DX,DI
	MOV	BX,SI
	DOWN
	MOV	DI,BX
	REPNZ
	SCAB
	MOV	BX,DI
	LAHF
	ADD	BX,CX
	RCR	SI
	SAHF
	RCL	SI
	ADC	AL,CH
	NOT	AL
	LAHF
	INC	BX
	SAHF
	JNZ	TARGET
	JNZ	RET
	JZ	L0000
	CALL	TARGET
L0000:	
	XCHG	DX,BX
	ORG	100H
	LAHF
	OR	AL,080H
 *** ERROR: Cannot determine bit number.
	SAHF
	LAHF
	AND	CH,0FEH
	SAHF
TARGET:	MOV	AL,0
